arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Pricing
cat > tests/CheckoutPricing.UnitTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotal(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Gold
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotal(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotal command) => command.Subtotal;
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

